public sealed class WorkflowPlayer : AxHost
{
    public WorkflowPlayer():base("6BF52A52-394A-11D3-B153-00C04F79FAA6"){Height=260;}
    public void Open(string path){dynamic player=GetOcx()!;player.settings.autoStart=false;player.URL=path;player.uiMode="full";}
    public void Seek(double seconds){dynamic player=GetOcx()!;player.controls.currentPosition=seconds;}
    protected override void Dispose(bool disposing){if(disposing&&IsHandleCreated){try{dynamic player=GetOcx()!;player.controls.stop();player.close();}catch{}}base.Dispose(disposing);}
}

